if (element.nextElementSibling && element.nextElementSibling.classList.contains('cta-button-inserted')) return;

var btn = document.createElement('a');
btn.href = 'https://support.fandom.com/hc/en-us/requests/new?ticket_form_id=360000931354&tf_360017817454=i_want_a_feature_or_extension_turned_on';
btn.target = '_self';
btn.rel = 'noopener';
btn.className = 'cta-button-inserted';
btn.textContent = 'Contact Us';
btn.style.display = 'inline-block';
btn.style.marginTop = '12px';
btn.style.padding = '12px 28px';
btn.style.background = '#1c4c9f';
btn.style.color = '#ffffff';
btn.style.fontWeight = '700';
btn.style.fontSize = '16px';
btn.style.borderRadius = '6px';
btn.style.border = 'none';
btn.style.cursor = 'pointer';
btn.style.textDecoration = 'none';
btn.style.transition = 'background 0.2s ease';
btn.style.boxShadow = '0 2px 6px rgba(0,0,0,0.2)';

var hoverStyle = document.createElement('style');
hoverStyle.textContent = 'a.cta-button-inserted:hover { background: #0e3a8a; }';
btn.appendChild(hoverStyle);

element.parentNode.insertBefore(btn, element.nextSibling);
